# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/utilities/encrypt-secure-property.yml
#   step   : "Download secure-properties-tool from Azure Artifacts" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
#
# Inputs (environment):
#   MDF_AZURE_FEED_URL    <- $(AZURE_FEED_URL)  [required]
#   MDF_SETTINGS_XML      <- $(settingsXml.secureFilePath)  [default: (empty)]
#   MDF_TOOL_ARTIFACT_ID  <- $(TOOL_ARTIFACT_ID)  [default: secure-properties-tool]
#   MDF_TOOL_GROUP_ID     <- $(TOOL_GROUP_ID)  [default: com.mulesoft.tools]
#   MDF_TOOL_VERSION      <- ${{ parameters.toolVersion }}  [default: 1.0.0]
# Outputs: TOOL_JAR_PATH (output)

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_AZURE_FEED_URL?MDF_AZURE_FEED_URL is required (Azure variable AZURE_FEED_URL)}"
: "${MDF_SETTINGS_XML=}"
: "${MDF_TOOL_ARTIFACT_ID=secure-properties-tool}"
: "${MDF_TOOL_GROUP_ID=com.mulesoft.tools}"
: "${MDF_TOOL_VERSION=1.0.0}"

# >>> extracted body
set -euo pipefail

TOOL_VERSION="${MDF_TOOL_VERSION}"
TOOL_JAR_NAME="${MDF_TOOL_ARTIFACT_ID}-${TOOL_VERSION}.jar"
DOWNLOAD_DIR="$(ci_temp_dir)/secure-tools"
mkdir -p "$DOWNLOAD_DIR"

# Build the direct Maven artifact URL (avoids mvn dependency:copy overhead)
GROUP_PATH="$(echo "${MDF_TOOL_GROUP_ID}" | tr '.' '/')"
DOWNLOAD_URL="${MDF_AZURE_FEED_URL}/${GROUP_PATH}/${MDF_TOOL_ARTIFACT_ID}/${TOOL_VERSION}/${TOOL_JAR_NAME}"

echo "Downloading ${TOOL_JAR_NAME} from Azure Artifacts..."
echo "URL: ${DOWNLOAD_URL}"

# Extract credentials from settings.xml for feed auth
SETTINGS_FILE="${MDF_SETTINGS_XML}"
FEED_USERNAME=$(grep -A2 '<id>azure-artifacts</id>' "$SETTINGS_FILE" | grep '<username>' | sed 's/.*<username>\(.*\)<\/username>.*/\1/' | head -1)
FEED_PASSWORD=$(grep -A3 '<id>azure-artifacts</id>' "$SETTINGS_FILE" | grep '<password>' | sed 's/.*<password>\(.*\)<\/password>.*/\1/' | head -1)

HTTP_STATUS=$(curl -sS -w "%{http_code}" -o "$DOWNLOAD_DIR/$TOOL_JAR_NAME" \
  -u "${FEED_USERNAME}:${FEED_PASSWORD}" \
  "$DOWNLOAD_URL")

TOOL_JAR="$DOWNLOAD_DIR/$TOOL_JAR_NAME"

if [[ "$HTTP_STATUS" != "200" ]] || [[ ! -s "$TOOL_JAR" ]]; then
  ci_log_error "Failed to download $TOOL_JAR_NAME (HTTP $HTTP_STATUS)."
  echo "Ensure the JAR is published to the feed with: mvn deploy:deploy-file ..."
  rm -f "$TOOL_JAR"
  exit 1
fi

echo "Downloaded: $TOOL_JAR ($(stat --printf='%s' "$TOOL_JAR" 2>/dev/null || stat -f%z "$TOOL_JAR") bytes)"
ci_set_var TOOL_JAR_PATH "$TOOL_JAR"
